namespace sv_1b6771a19dcb4a73b101647ed7c64b98.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the current warehouse selection
/// and notifies all subscribed components when it changes.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses = new List<(string, string)>
    {
        ("wh-a", "Warehouse A"),
        ("wh-b", "Warehouse B"),
        ("wh-c", "Warehouse C"),
        ("wh-d", "Warehouse D")
    };

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId).Name ?? _currentWarehouseId;

    public event Func<Task>? OnWarehouseChanged;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;

        if (OnWarehouseChanged is not null)
        {
            await OnWarehouseChanged.Invoke();
        }
    }
}

namespace sv_1b6771a19dcb4a73b101647ed7c64b98.Services;

/// <summary>
/// Scoped service (per-circuit) that provides low-stock alert counts
/// and notifies subscribers when new data arrives.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    private int _lastLowStockCount;
    public int LastLowStockCount => _lastLowStockCount;

    /// <summary>
    /// Fired when alert data has been refreshed. All subscribed components
    /// should re-render when this fires.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock level.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Refreshes the alert count for the given warehouse and notifies all subscribers.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        _lastLowStockCount = await GetLowStockCountAsync(warehouseId);

        if (OnAlertDataChanged is not null)
        {
            await OnAlertDataChanged.Invoke();
        }
    }
}

