@page "/dashboard"
@using sv_1b6771a19dcb4a73b101647ed7c64b98.Services
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService

<PageTitle>Dashboard</PageTitle>

<h3>Dashboard — @WarehouseState.CurrentWarehouseName</h3>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4">
                    <AlertBadge />
                </p>
                <p class="text-muted small">
                    Polling every 10 seconds
                    @if (_isPolling)
                    {
                        <span class="ms-2 spinner-border spinner-border-sm" role="status"></span>
                    }
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Recent Activity</h5>
                <ul class="list-group list-group-flush">
                    @foreach (var entry in _activityLog.TakeLast(8).Reverse())
                    {
                        <li class="list-group-item small">@entry</li>
                    }
                </ul>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private readonly List<string> _activityLog = new();

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;

        // Initial fetch
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        LogActivity($"Initial load: {AlertService.LastLowStockCount} low-stock items");

        // Start polling
        _cts = new CancellationTokenSource();
        _ = PollAsync(_cts.Token);
    }

    private async Task PollAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _isPolling = true;

        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
                LogActivity($"Poll: {AlertService.LastLowStockCount} low-stock items at {DateTime.Now:T}");
                await InvokeAsync(StateHasChanged);
            }
        }
        catch (OperationCanceledException) { }
        finally
        {
            _isPolling = false;
        }
    }

    private async Task HandleWarehouseChanged()
    {
        LogActivity($"Switched to {WarehouseState.CurrentWarehouseName}");
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        LogActivity($"Refreshed: {AlertService.LastLowStockCount} low-stock items");
        await InvokeAsync(StateHasChanged);
    }

    private async Task HandleAlertDataChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private void LogActivity(string message)
    {
        _activityLog.Add($"[{DateTime.Now:HH:mm:ss}] {message}");
    }

    public async ValueTask DisposeAsync()
    {
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

